class WholesaleCommercialRecommendation{final String key,type,entityKey,title,entityName,severity,metricLabel,actionText,rationale,reviewStatus,reviewNote;final double metricValue,currentValue,recommendedValue;const WholesaleCommercialRecommendation({required this.key,required this.type,required this.entityKey,required this.title,required this.entityName,required this.severity,required this.metricLabel,required this.actionText,required this.rationale,required this.reviewStatus,required this.reviewNote,required this.metricValue,required this.currentValue,required this.recommendedValue});factory WholesaleCommercialRecommendation.fromSupabase(Map<String,dynamic>d){double n(dynamic v)=>v is num?v.toDouble():double.tryParse(v?.toString()??'')??0;return WholesaleCommercialRecommendation(key:(d['recommendation_key']??'').toString(),type:(d['recommendation_type']??'').toString(),entityKey:(d['entity_key']??'').toString(),title:(d['title']??'Recommendation').toString(),entityName:(d['entity_name']??'').toString(),severity:(d['severity']??'medium').toString(),metricLabel:(d['metric_label']??'').toString(),actionText:(d['action_text']??'').toString(),rationale:(d['rationale']??'').toString(),reviewStatus:(d['review_status']??'open').toString(),reviewNote:(d['review_note']??'').toString(),metricValue:n(d['metric_value']),currentValue:n(d['current_value']),recommendedValue:n(d['recommended_value']));}}
Future<List<WholesaleCommercialRecommendation>> fetchCommercialRecommendations(int days)async{await requireAdminAccess();final r=await supabase.rpc('admin_list_wholesale_commercial_recommendations',params:{'p_days':days,'p_limit':250});return (r as List).map((x)=>WholesaleCommercialRecommendation.fromSupabase(Map<String,dynamic>.from(x as Map))).toList();}
Future<void> updateCommercialRecommendation(WholesaleCommercialRecommendation r,String status,String note)async{await requireAdminAccess();await supabase.rpc('admin_update_wholesale_commercial_review',params:{'p_recommendation_key':r.key,'p_recommendation_type':r.type,'p_entity_key':r.entityKey,'p_status':status,'p_note':note.trim()});}
