@override Widget build(BuildContext context){return Scaffold(backgroundColor:FarmColors.background,appBar:AppBar(title:const Text('Commercial Recommendations')),body:FutureBuilder<List<WholesaleCommercialRecommendation>>(future:_future,builder:(context,s){if(s.connectionState==ConnectionState.waiting&&s.data==null)return const Center(child:CircularProgressIndicator());if(s.hasError&&s.data==null)return Center(child:Text(friendlyAppError(s.error!)));final all=s.data??const<WholesaleCommercialRecommendation>[];final rows=_filter=='all'?all:all.where((r)=>r.reviewStatus==_filter).toList();final critical=all.where((r)=>r.severity=='critical'&&r.reviewStatus=='open').length;return RefreshIndicator(onRefresh:_refresh,child:ListView(physics:const AlwaysScrollableScrollPhysics(),padding:const EdgeInsets.fromLTRB(16,16,16,110),children:[FarmCard(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Commercial Action Queue',style:TextStyle(fontSize:17,fontWeight:FontWeight.w900)),const SizedBox(height:4),const Text('Advisory recommendations from price, customer, supplier and route economics. Nothing changes automatically; HPJ records your review decision.',style:TextStyle(color:FarmColors.mutedText,fontSize:10.5,height:1.35,fontWeight:FontWeight.w600)),const SizedBox(height:8),Text('$critical critical open recommendation(s).',style:TextStyle(color:critical>0?FarmColors.danger:FarmColors.success,fontWeight:FontWeight.w900))])),const SizedBox(height:10),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:[30,90].map((x)=>Padding(padding:const EdgeInsets.only(right:7),child:ChoiceChip(label:Text('$x days'),selected:_days==x,onSelected:(_){setState((){_days=x;_future=fetchCommercialRecommendations(_days);});}))).toList())),const SizedBox(height:8),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:['open','acknowledged','resolved','ignored','all'].map((x)=>Padding(padding:const Ed